func newLedgerEntry() unsafe.Pointer { return unsafe.Pointer(new(carriersettlement.LedgerEntry)) }

func newNLedgerEntry(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]carriersettlement.LedgerEntry, n)))
}

func ptrLedgerEntry(p unsafe.Pointer, c int32) any {
	r := (*carriersettlement.LedgerEntry)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.CarrierID))
	case 4:
		return (*string)(unsafe.Pointer(&r.EntryType))
	case 5:
		return &r.SourceObjectType
	case 6:
		return &r.SourceObjectID
	case 7:
		return &r.SourceEventType
	case 8:
		return (**string)(unsafe.Pointer(&r.RelatedSettlementID))
	case 9:
		return (**string)(unsafe.Pointer(&r.JournalBatchID))
	case 10:
		return &r.DocumentNumber
	case 11:
		return &r.TransactionDate
	case 12:
		return (*int64)(unsafe.Pointer(&r.LineNumber))
	case 13:
		return &r.AmountMinor
	case 14:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 15:
		return &r.CreatedAt
	}
	return nil
}

func valueLedgerEntry(p unsafe.Pointer, c int32) any {
	r := (*carriersettlement.LedgerEntry)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.CarrierID)
	case 4:
		return string(r.EntryType)
	case 5:
		return r.SourceObjectType
	case 6:
		return r.SourceObjectID
	case 7:
		return r.SourceEventType
	case 8:
		if r.RelatedSettlementID == nil {
			return nil
		}
		return string(*r.RelatedSettlementID)
	case 9:
		if r.JournalBatchID == nil {
			return nil
		}
		return string(*r.JournalBatchID)
	case 10:
		if r.DocumentNumber == "" {
			return nil
		}
		return r.DocumentNumber
	case 11:
		return r.TransactionDate
	case 12:
		return int64(r.LineNumber)
	case 13:
		return r.AmountMinor
	case 14:
		return string(r.CreatedByID)
	case 15:
		return r.CreatedAt
	}
	return nil
}

func attachLedgerEntry(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*carriersettlement.LedgerEntry)(p)
	switch rel {
	case 0:
		r.Carrier = (*carrier.Carrier)(child)
	}
}

func beforeCreateLedgerEntry(ctx context.Context, p unsafe.Pointer) error {
	return (*carriersettlement.LedgerEntry)(p).BeforeCreate(ctx)
}

